-- Ledger core schema: the one trusted record of all money.
-- Every user-owned table: user_id uuid not null default auth.uid(), RLS user_id = auth.uid().
-- IDs are uuids generated by the client (crypto.randomUUID()) so retries are idempotent.
-- Money is numeric(14,2), signed on entries: negative = money out (rule-signed-money).

-- ---------------------------------------------------------------------------
-- helpers
-- ---------------------------------------------------------------------------

create or replace function private.touch_updated_at() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  return new;
end $$;

-- Deterministic uuid for a legacy (localStorage) id, namespaced per user so two
-- users importing the demo never collide. uuid-v5 style, built on md5.
create or replace function public.legacy_uuid(p_user uuid, p_kind text, p_legacy text)
returns uuid language sql immutable set search_path = '' as $$
  select case
    when p_legacy ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then p_legacy::uuid
    else md5('ledger:' || p_user::text || ':' || p_kind || ':' || p_legacy)::uuid
  end
$$;

-- The user every function acts for. Authenticated callers always act as themselves;
-- a service-role caller (cron / edge function) must name the user explicitly.
create or replace function public.ledger_uid(p_user uuid default null) returns uuid
language plpgsql stable set search_path = '' as $$
declare v uuid := auth.uid();
begin
  if v is not null then
    if p_user is not null and p_user <> v then
      raise exception 'p_user must be the caller' using errcode = '42501';
    end if;
    return v;
  end if;
  if p_user is not null and current_user in ('service_role', 'postgres', 'supabase_admin') then
    return p_user;
  end if;
  raise exception 'not authenticated' using errcode = '28000';
end $$;

-- JS Math.round (half toward +infinity), so SQL numbers match src/lib exactly.
create or replace function public.js_round(x numeric) returns numeric
language sql immutable set search_path = '' as $$ select floor(x + 0.5) $$;

-- ---------------------------------------------------------------------------
-- categories (global reference data; readable by every signed-in user)
-- ---------------------------------------------------------------------------

create table public.categories (
  code        text primary key,          -- exactly the TS Category string, e.g. 'Food & drink'
  label       text not null,
  kind        text not null check (kind in ('expense', 'income', 'transfer', 'invest', 'adjustment')),
  is_spend    boolean not null,          -- a negative, unrefunded entry in this category is spending
  is_fixed    boolean not null default false, -- bills on a date (selectors.ts FIXED): never paced
  is_monthly  boolean not null default false, -- today.ts MONTHLY: comes out of the pool from tomorrow
  sort        int not null
);

insert into public.categories (code, label, kind, is_spend, is_fixed, is_monthly, sort) values
  ('Food & drink',  'Food & drink',  'expense',    true,  false, false, 1),
  ('Groceries',     'Groceries',     'expense',    true,  false, true,  2),
  ('Transport',     'Transport',     'expense',    true,  false, false, 3),
  ('Shopping',      'Shopping',      'expense',    true,  false, false, 4),
  ('Rent & bills',  'Rent & bills',  'expense',    true,  true,  true,  5),
  ('Subscriptions', 'Subscriptions', 'expense',    true,  true,  true,  6),
  ('Gifts',         'Gifts',         'expense',    true,  false, false, 7),
  ('Household',     'Household',     'expense',    true,  false, true,  8),
  ('Health',        'Health',        'expense',    true,  false, false, 9),
  ('Salary',        'Salary',        'income',     false, false, false, 10),
  ('Income',        'Income',        'income',     false, false, false, 11),
  ('Investments',   'Investments',   'invest',     false, false, false, 12),
  ('Transfer',      'Transfer',      'transfer',   false, false, false, 13),
  ('Other',         'Other',         'expense',    true,  false, false, 14),
  ('Adjustment',    'Adjustment',    'adjustment', false, false, false, 15);

-- ---------------------------------------------------------------------------
-- profiles
-- ---------------------------------------------------------------------------

create table public.profiles (
  user_id           uuid primary key default auth.uid() references auth.users (id) on delete cascade,
  name              text not null default '',
  initials          text not null default '',
  income            numeric(14,2) not null default 0,   -- per payday, take-home
  frequency         text not null default 'Twice a month'
                    check (frequency in ('Twice a month', 'Monthly', 'Weekly', 'Irregular')),
  side_income       jsonb not null default '[]',        -- SideIncome[] as in types.ts
  monthly_budget    numeric(14,2) not null default 0,   -- 0 = use suggested budget
  category_budgets  jsonb not null default '{}',        -- { "<category code>": amount }
  timezone          text not null default 'Asia/Manila',
  onboarded         boolean not null default false,
  push_enabled      boolean not null default false,
  push_quiet_start  time not null default '22:00',
  push_quiet_end    time not null default '07:00',
  push_max_per_week int not null default 3 check (push_max_per_week between 0 and 3),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- accounts. Balance is NEVER stored: see view account_balances.
-- opening_balance is in display terms (credit: amount owed, positive).
-- ---------------------------------------------------------------------------

create table public.accounts (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name             text not null,
  provider         text not null default 'other'
                   check (provider in ('gcash','bpi','bdo','maya','maribank','rcbc','unionbank','ibkr','cash','other')),
  provider_label   text not null default '',
  type             text not null check (type in ('bank', 'investments', 'ewallet', 'cash', 'credit')),
  kind             text not null default '',
  last4            text check (last4 is null or last4 ~ '^[0-9]{4}$'),
  rate             text,
  due_date         date,
  currency         text not null default 'PHP',
  opening_balance  numeric(14,2) not null default 0,
  opening_date     timestamptz not null default now(),
  archived_at      timestamptz,
  legacy_id        text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (id, user_id)
);
create index accounts_user_idx on public.accounts (user_id);

create table public.account_aliases (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null default auth.uid() references auth.users (id) on delete cascade,
  account_id  uuid not null,
  alias       text not null,
  created_at  timestamptz not null default now(),
  foreign key (account_id, user_id) references public.accounts (id, user_id) on delete cascade
);
create unique index account_aliases_unique on public.account_aliases (user_id, lower(alias));

-- ---------------------------------------------------------------------------
-- raw inputs (what was captured: text, voice clip, photo)
-- ---------------------------------------------------------------------------

create table public.raw_inputs (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null default auth.uid() references auth.users (id) on delete cascade,
  kind          text not null check (kind in ('text', 'voice', 'photo')),
  text          text,
  storage_path  text,          -- '<user_id>/<file>' inside bucket 'voice' or 'receipts'
  transcript    text,
  model         text,
  parsed        jsonb,
  gate          jsonb,
  created_at    timestamptz not null default now(),
  unique (id, user_id)
);

-- ---------------------------------------------------------------------------
-- moves: a transfer or investment = two (or more) legs that sum to zero
-- ---------------------------------------------------------------------------

create table public.moves (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null default auth.uid() references auth.users (id) on delete cascade,
  kind        text not null check (kind in ('transfer', 'invest')),
  legacy_id   text,
  created_at  timestamptz not null default now(),
  unique (id, user_id)
);

-- ---------------------------------------------------------------------------
-- rules (learned) and corrections (append-only)
-- ---------------------------------------------------------------------------

create table public.corrections (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null default auth.uid() references auth.users (id) on delete cascade,
  entry_id      uuid,
  raw_input_id  uuid,
  before        jsonb not null,
  after         jsonb not null,
  created_at    timestamptz not null default now()
);

create table public.rules (
  id                    uuid primary key default gen_random_uuid(),
  user_id               uuid not null default auth.uid() references auth.users (id) on delete cascade,
  match                 jsonb not null,   -- e.g. {"merchant": "grab"} / {"text_contains": "palengke"}
  "set"                 jsonb not null,   -- e.g. {"category_code": "Transport", "account_id": "..."}
  hits                  int not null default 0,
  source_correction_id  uuid references public.corrections (id) on delete set null,
  active                boolean not null default true,
  last_hit_at           timestamptz,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- entries
-- ---------------------------------------------------------------------------

create table public.entries (
  id                  uuid primary key default gen_random_uuid(),
  user_id             uuid not null default auth.uid() references auth.users (id) on delete cascade,
  account_id          uuid,
  category_code       text references public.categories (code) on update cascade,
  amount              numeric(14,2) not null check (amount <> 0),
  currency            text not null default 'PHP',
  occurred_at         timestamptz not null default now(),
  description         text not null default '',
  merchant            text,
  status              text not null default 'posted' check (status in ('posted', 'review', 'void')),
  review_question     text,
  refunded_at         timestamptz,
  move_id             uuid,
  raw_input_id        uuid,
  raw                 text,                 -- Entry.raw: what the user typed/said
  source              text check (source in ('voice', 'receipt')),
  created_by          text not null default 'owner' check (created_by in ('owner', 'claude', 'rule')),
  rule_id             uuid references public.rules (id) on delete set null,
  auto                boolean not null default false,
  method              text,
  receipt_image_path  text,                 -- '<user_id>/<file>' in bucket 'receipts'
  legacy_id           text,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (id, user_id),
  foreign key (account_id, user_id) references public.accounts (id, user_id) on delete set null (account_id),
  foreign key (move_id, user_id) references public.moves (id, user_id) on delete set null (move_id),
  foreign key (raw_input_id, user_id) references public.raw_inputs (id, user_id) on delete set null (raw_input_id),
  -- refund is only for expenses, never a leg of a move (D-0009)
  constraint entries_refund_expense_only check (refunded_at is null or (amount < 0 and move_id is null))
);
create index entries_user_time_idx on public.entries (user_id, occurred_at desc);
create index entries_account_idx on public.entries (account_id);
create index entries_move_idx on public.entries (move_id) where move_id is not null;
create index entries_desc_trgm on public.entries
  using gin (lower(description || ' ' || coalesce(merchant, '')) extensions.gin_trgm_ops);

alter table public.corrections
  add foreign key (entry_id) references public.entries (id) on delete set null;

-- a receipt spread over several categories; amounts positive
create table public.entry_splits (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null default auth.uid() references auth.users (id) on delete cascade,
  entry_id       uuid not null,
  category_code  text not null references public.categories (code) on update cascade,
  amount         numeric(14,2) not null check (amount > 0),
  items          text[] not null default '{}',
  position       int not null default 0,
  foreign key (entry_id, user_id) references public.entries (id, user_id) on delete cascade
);
create index entry_splits_entry_idx on public.entry_splits (entry_id);

create table public.receipt_items (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null default auth.uid() references auth.users (id) on delete cascade,
  entry_id       uuid not null,
  name           text not null,
  amount         numeric(14,2) not null check (amount >= 0),
  category_code  text references public.categories (code) on update cascade,
  unsure         boolean not null default false,
  position       int not null default 0,
  foreign key (entry_id, user_id) references public.entries (id, user_id) on delete cascade
);
create index receipt_items_entry_idx on public.receipt_items (entry_id);

-- ---------------------------------------------------------------------------
-- snapshots and fx
-- ---------------------------------------------------------------------------

create table public.balance_snapshots (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null default auth.uid() references auth.users (id) on delete cascade,
  account_id    uuid not null,
  as_of         timestamptz not null default now(),
  reported      numeric(14,2) not null,   -- display terms (credit: amount owed)
  raw_input_id  uuid,
  created_at    timestamptz not null default now(),
  foreign key (account_id, user_id) references public.accounts (id, user_id) on delete cascade,
  foreign key (raw_input_id, user_id) references public.raw_inputs (id, user_id) on delete set null (raw_input_id)
);
create index balance_snapshots_account_idx on public.balance_snapshots (account_id, as_of desc);

create table public.holding_snapshots (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null default auth.uid() references auth.users (id) on delete cascade,
  account_id  uuid not null,
  as_of       timestamptz not null default now(),
  symbol      text not null,
  name        text not null default '',
  qty         numeric(20,6) not null,
  price       numeric(20,6) not null,      -- per unit, in `currency`
  value       numeric(14,2) not null,      -- market value in `currency`
  change_pct  numeric(8,2),
  currency    text not null default 'PHP',
  created_at  timestamptz not null default now(),
  foreign key (account_id, user_id) references public.accounts (id, user_id) on delete cascade
);
create index holding_snapshots_account_idx on public.holding_snapshots (account_id, as_of desc);

create table public.fx_rates (
  user_id      uuid not null default auth.uid() references auth.users (id) on delete cascade,
  currency     text not null,
  as_of        date not null,
  rate_to_php  numeric(18,8) not null check (rate_to_php > 0),
  primary key (user_id, currency, as_of)
);

-- ---------------------------------------------------------------------------
-- knowledge base
-- ---------------------------------------------------------------------------

create table public.goals (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name         text not null,
  saved        numeric(14,2) not null default 0,
  target       numeric(14,2) not null check (target >= 0),
  by_month     text not null default '' check (by_month ~ '^([0-9]{4}-(0[1-9]|1[0-2]))?$'), -- 'YYYY-MM' or ''
  archived_at  timestamptz,
  legacy_id    text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create table public.recurring_items (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null default auth.uid() references auth.users (id) on delete cascade,
  description    text not null,
  merchant       text,
  category_code  text references public.categories (code) on update cascade,
  account_id     uuid,
  amount         numeric(14,2) not null check (amount <> 0),   -- signed, as the entry would be
  cadence        text not null check (cadence in ('monthly', 'weekly')),
  day_of_month   int check (day_of_month between 1 and 31),  -- monthly
  weekday        int check (weekday between 0 and 6),        -- weekly, 0 = Sunday
  starts_on      date not null default current_date,
  active         boolean not null default true,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  foreign key (account_id, user_id) references public.accounts (id, user_id) on delete set null (account_id),
  check ((cadence = 'monthly' and day_of_month is not null) or (cadence = 'weekly' and weekday is not null))
);

-- ---------------------------------------------------------------------------
-- audit: append-only, written only by trigger
-- ---------------------------------------------------------------------------

create table public.entry_events (
  id                uuid primary key default gen_random_uuid(),
  seq               bigint generated always as identity unique,
  user_id           uuid not null references auth.users (id) on delete cascade,
  batch_id          uuid not null,     -- one per transaction: what one undo reverses
  entry_id          uuid not null,     -- no FK: the entry may be gone
  op                text not null check (op in ('insert', 'update', 'void', 'refund', 'delete')),
  before            jsonb,
  after             jsonb,
  reverts_batch_id  uuid,              -- set when this event was written by undo_event
  actor             uuid,              -- auth.uid() at the time (null = service role)
  created_at        timestamptz not null default now()
);
create index entry_events_batch_idx on public.entry_events (batch_id);
create index entry_events_entry_idx on public.entry_events (entry_id, seq);

-- ---------------------------------------------------------------------------
-- insights and notifications
-- ---------------------------------------------------------------------------

create table public.insights (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null default auth.uid() references auth.users (id) on delete cascade,
  kind             text not null check (kind in ('daily', 'weekly', 'monthly', 'alert', 'answer')),
  period_start     timestamptz,
  period_end       timestamptz,
  fingerprint      text not null,
  metrics          jsonb not null default '{}',
  narrative        text,
  cited_entry_ids  uuid[] not null default '{}',
  stale            boolean not null default false,
  read_at          timestamptz,
  dismissed_at     timestamptz,
  pushed_at        timestamptz,
  created_at       timestamptz not null default now(),
  unique (user_id, kind, fingerprint)
);

create table public.push_subscriptions (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null default auth.uid() references auth.users (id) on delete cascade,
  endpoint      text not null unique,
  p256dh        text not null,
  auth          text not null,
  user_agent    text,
  created_at    timestamptz not null default now(),
  last_used_at  timestamptz
);

create table public.notification_log (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null default auth.uid() references auth.users (id) on delete cascade,
  insight_id  uuid references public.insights (id) on delete set null,
  channel     text not null default 'push' check (channel in ('push')),
  status      text not null check (status in ('sent', 'skipped', 'failed')),
  reason      text,
  sent_at     timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- updated_at
-- ---------------------------------------------------------------------------

create trigger touch before update on public.profiles        for each row execute function private.touch_updated_at();
create trigger touch before update on public.accounts        for each row execute function private.touch_updated_at();
create trigger touch before update on public.entries         for each row execute function private.touch_updated_at();
create trigger touch before update on public.rules           for each row execute function private.touch_updated_at();
create trigger touch before update on public.goals           for each row execute function private.touch_updated_at();
create trigger touch before update on public.recurring_items for each row execute function private.touch_updated_at();

-- ---------------------------------------------------------------------------
-- row level security
-- ---------------------------------------------------------------------------

alter table public.categories enable row level security;
create policy categories_read on public.categories for select to authenticated using (true);

do $$
declare t text;
begin
  foreach t in array array[
    'profiles','accounts','account_aliases','raw_inputs','moves','rules','entries','entry_splits',
    'receipt_items','balance_snapshots','holding_snapshots','fx_rates','goals','recurring_items',
    'insights','push_subscriptions','notification_log'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format(
      'create policy owner_all on public.%I for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid())', t);
  end loop;
end $$;

-- append-only tables: read own rows; corrections may be inserted, never changed
alter table public.entry_events enable row level security;
create policy owner_read on public.entry_events for select to authenticated using (user_id = auth.uid());
revoke insert, update, delete, truncate on public.entry_events from anon, authenticated;

alter table public.corrections enable row level security;
create policy owner_read on public.corrections for select to authenticated using (user_id = auth.uid());
create policy owner_insert on public.corrections for insert to authenticated with check (user_id = auth.uid());
revoke update, delete, truncate on public.corrections from anon, authenticated;

-- reference data is maintained by migrations only
revoke insert, update, delete, truncate on public.categories from anon, authenticated;
